import sys
from collections import defaultdict

def solve():
    input = sys.stdin.read().split('\n')
    ptr = 0
    t = int(input[ptr])
    ptr += 1
    for _ in range(t):
        while ptr < len(input) and input[ptr].strip() == '':
            ptr += 1
        if ptr >= len(input):
            break
        n, m = map(int, input[ptr].split())
        ptr += 1
        adj = defaultdict(list)
        degree = [0] * (n + 1)
        for __ in range(m):
            a, b = map(int, input[ptr].split())
            adj[a].append(b)
            adj[b].append(a)
            degree[a] += 1
            degree[b] += 1
            ptr += 1

        found = False
        for mask in range(1, 1 << n):
            if bin(mask).count('1') < 2 or bin(mask).count('1') == n:
                continue
            S = []
            for i in range(1, n+1):
                if mask & (1 << (i-1)):
                    S.append(i)
            if len(S) < 2 or len(S) == n:
                continue
            # Check if removing S preserves degrees mod 3
            valid = True
            for v in range(1, n+1):
                if v in S:
                    continue
                original_deg = degree[v]
                new_deg = original_deg
                for u in adj[v]:
                    if u in S:
                        new_deg -= 1
                if new_deg % 3 != original_deg % 3:
                    valid = False
                    break
            if valid:
                print("Yes")
                print(len(S))
                print(' '.join(map(str, S)))
                found = True
                break
        if not found:
            print("No")

solve()
